'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),path=require('node:path');
const root=path.resolve(__dirname,'../..'),source=fs.readFileSync(path.join(root,'releases/v280/lts-v225-open-finance.js'),'utf8');
const snippet=source.split('// BEGIN PURE FRESHNESS MODEL:')[1].split('// END PURE FRESHNESS MODEL')[0];
const model=vm.runInNewContext(snippet.slice(snippet.indexOf('function createFreshnessModel'))+';createFreshnessModel();',{Intl,Date,Map});
const now=Date.parse('2026-09-20T09:00:00Z'),receipt='2026-09-20T08:30:00Z',origin='2026-09-19T18:00:00Z';
const row=(override={})=>({id:'synthetic-connection-a',provider:'synthetic-provider',institution_code:'341',last_success_at:receipt,provider_item_updated_at:origin,status:'connected',...override});
const status=(...rows)=>({connections:rows});
const checks=[];function check(name,fn){fn();checks.push(name)}
const normalized=v=>JSON.parse(JSON.stringify(v));
check('Previous BRT day under 24h is visible without cadence failure',()=>{const x=model.describe(row(),null,now);assert.equal(x.level,'previous-day');assert.equal(x.failed,false);assert.equal(x.ageHours,15);assert.equal(x.balanceCurrent,false);assert.equal(x.balanceTime,null)});
check('Same UTC date across BRT midnight is previous local day',()=>assert.equal(model.describe(row({last_success_at:'2026-09-20T03:10:00Z',provider_item_updated_at:'2026-09-20T02:50:00Z'}),null,Date.parse('2026-09-20T03:15:00Z')).level,'previous-day'));
check('Different UTC days on same BRT date are not previous local day',()=>assert.equal(model.describe(row({last_success_at:'2026-09-20T01:00:00Z',provider_item_updated_at:'2026-09-19T23:50:00Z'}),null,Date.parse('2026-09-20T01:10:00Z')).level,'same-day'));
check('Exactly 24h is independent age signal, never ingestion failure',()=>{const x=model.describe(row({provider_item_updated_at:'2026-09-19T09:00:00Z'}),null,now);assert.equal(x.level,'aged');assert.equal(x.failed,false)});
check('Missing, invalid, impossible calendar day and future never certify balance',()=>{for(const input of [null,'','not-a-date','2026-02-30T12:00:00Z','2026-09-20T24:00:00Z','2026-09-20T08:99:00Z','2026-09-20T10:00:00Z']){const x=model.describe(row({provider_item_updated_at:input}),null,now);assert.equal(x.level,'unknown');assert.equal(x.balanceCurrent,false);assert.equal(x.balanceTime,null)}});
check('Source later than receipt is inconsistent even if not in future',()=>assert.equal(model.describe(row({provider_item_updated_at:'2026-09-20T08:40:00Z'}),null,now).level,'unknown'));
check('Missing receipt cannot turn a connection timestamp into freshness evidence',()=>assert.equal(model.describe(row({last_success_at:null,provider_item_updated_at:'2026-09-20T08:00:00Z'}),null,now).level,'unknown'));
check('Explicit offset and Z represent same instant',()=>assert.equal(model.timestamp('2026-09-20T05:30:00-03:00',now).time,model.timestamp(receipt,now).time));
check('Formatter explicitly presents BRT',()=>assert.match(model.describe(row(),null,now).received,/20\/09\/2026,? 05:30 BRT/));
check('New receipt with same origin keeps absence-of-new-position warning',()=>{const before=model.observe(status(row({last_success_at:'2026-09-20T07:00:00Z'})),null,now);const current=model.observe(status(row()),before,now);assert.equal(current.get(model.identity(row())).change,'unchanged');assert.match(model.describe(row(),current,now).warning,/sem nova posição confirmada/);assert.match(model.collectionMessage(status(row()),before,now),/mesma origem de conexão em Itaú/)});
check('Repeated identical reads preserve warning without duplicate state',()=>{let history=model.observe(status(row({last_success_at:'2026-09-20T07:00:00Z'})),null,now);history=model.observe(status(row()),history,now);for(let i=0;i<20;i++)history=model.observe(status(row()),history,now);assert.equal(history.size,1);assert.equal(history.get(model.identity(row())).change,'unchanged')});
check('Item advance never certifies account balance',()=>{const a=row({last_success_at:'2026-09-20T07:00:00Z'}),b=row({provider_item_updated_at:'2026-09-20T08:00:00Z'}),history=model.observe(status(b),model.observe(status(a),null,now),now),x=model.describe(b,history,now);assert.equal(x.change,'advanced');assert.equal(x.balanceCurrent,false);assert.match(x.warning,/data de cada saldo continua não informada/)});
check('Regressing origin in a newer receipt remains visibly unconfirmed',()=>{const a=row({last_success_at:'2026-09-20T07:00:00Z',provider_item_updated_at:'2026-09-20T06:00:00Z'}),history=model.observe(status(row()),model.observe(status(a),null,now),now);assert.equal(model.describe(row(),history,now).change,'regressed')});
check('Connection identities prevent cross-account/provider comparisons',()=>{const before=model.observe(status(row({last_success_at:'2026-09-20T07:00:00Z'})),null,now);for(const override of [{id:'synthetic-connection-b'},{institution_code:'237'},{provider:'synthetic-other-provider'},{id:null}]){const after=row(override);assert.equal(model.describe(after,model.observe(status(after),before,now),now).change,'unknown')}});
check('Duplicate identity is ambiguous and never claims freshness',()=>{const x=model.rows(status(row(),row()),null,now,['341']);assert.equal(x.length,2);for(const y of x){assert.equal(y.level,'unknown');assert.equal(y.change,'unknown')}});
check('Multiple connections in same bank remain distinct',()=>{const x=model.rows(status(row(),row({id:'synthetic-b',provider_item_updated_at:null})),null,now,['341']);assert.equal(x.length,2);assert.equal(x[0].level,'previous-day');assert.equal(x[1].level,'unknown')});
check('Selected account only renders its bank; unknown never falls back to consolidated',()=>{assert.equal(model.rows(status(row(),row({id:'synthetic-b',institution_code:'237'})),null,now,['237'])[0].code,'237');assert.equal(model.rows(status(row()),null,now,[]).length,0)});
check('Missing banks remain explicit instead of disappearing',()=>{const x=model.rows(status(row()),null,now);assert.equal(x.length,3);assert.equal(x.filter(r=>r.level==='unknown').length,2)});
check('Out-of-order receipt cannot overwrite newer source pair',()=>{const a=row(),b=row({last_success_at:'2026-09-20T07:00:00Z',provider_item_updated_at:'2026-09-18T18:00:00Z'});const merged=model.accept(status(a),status(b),now);assert.equal(merged.connections[0].last_success_at,receipt);assert.equal(merged.connections[0].provider_item_updated_at,origin)});
check('Concurrent bank updates are handled independently',()=>{const a=row(),b=row({id:'synthetic-b',institution_code:'237',last_success_at:'2026-09-20T07:00:00Z'}),nextA=row({last_success_at:'2026-09-20T07:00:00Z'}),nextB={...b,last_success_at:receipt};const x=model.accept(status(a,b),status(nextA,nextB),now).connections;assert.equal(x[0].last_success_at,receipt);assert.equal(x[1].last_success_at,receipt)});
check('Newest failure metadata survives an older receipt response',()=>{const x=model.accept(status(row()),status(row({last_success_at:'2026-09-20T07:00:00Z',last_attempt_at:'2026-09-20T08:50:00Z',last_error_code:'synthetic-error'})),now);assert.equal(model.describe(x.connections[0],null,now).failed,true)});
check('Future attempts are not trusted as failure evidence',()=>assert.equal(model.describe(row({last_attempt_at:'2026-09-21T08:00:00Z',last_error_code:'synthetic-error'}),null,now).failed,false));
check('Input financial values and dates are immutable; no financial fields emitted',()=>{const s=status(row({balance:123.45,currency:'BRL',transactions:[{id:'synthetic-pending',status:'PENDING',amount:-12}]})),before=JSON.stringify(s);Object.freeze(s.connections[0]);Object.freeze(s.connections);Object.freeze(s);const history=model.observe(s,null,now);model.accept(s,s,now);const x=model.rows(s,history,now);assert.equal(JSON.stringify(s),before);for(const y of x)assert.equal('balance' in y,false)});
check('No new RPC names, timers, observer or external storage introduced',()=>{const baseline=fs.readFileSync(path.join(root,'releases/v276/lts-v225-open-finance.js'),'utf8'),rpc=s=>[...s.matchAll(/rpc\('([^']+)'/g)].map(m=>m[1]).sort();assert.deepEqual(rpc(source),rpc(baseline));for(const regex of [/setTimeout\(/g,/setInterval\(/g,/MutationObserver/g,/fetch\(/g,/localStorage/g])assert.equal((source.match(regex)||[]).length,(baseline.match(regex)||[]).length)});
check('Visible panel is not a disclosure and never renders input amounts',()=>{const body=source.slice(source.indexOf('function freshnessMarkup('),source.indexOf('function paintFreshness('));assert(!body.includes('<details'));assert(!body.includes('.balance'));assert(body.includes('A data de alguns saldos não está confirmada'))});
const banks=[['341','Itaú',80],['237','Bradesco',20],['336','C6',0]];
const cash=()=>({status:'ready',date:'2026-09-20',data:{as_of:'2026-09-20',status:'complete',cash:100,day:Object.fromEntries(banks.map(([,name,balance])=>[name,{balance,net:null}])),bank_positions:banks.map(([institution_code,institution,balance],i)=>({institution_code,institution,balance,as_of:origin,source_id:'synthetic-position-'+i}))}});
check('Account provenance requires same ready day payload and matching bank/value',()=>{const x=model.positionRows(cash(),true,now);assert.equal(x.length,3);assert.equal(x[0].code,'341');assert.equal(x[0].level,'previous-day');assert.match(x[0].label,/19\/09\/2026,? 15:00 BRT/)});
check('Incomplete, cached/error, old day and absent metadata expose no account time',()=>{const variants=[cash(),cash(),cash(),cash(),cash()];variants[0].status='error';variants[1].date='2026-09-19';variants[2].data.as_of='2026-09-19';variants[3].data.status='incomplete';delete variants[4].data.bank_positions;for(const c of variants)assert.equal(model.positionRows(c,true,now).length,0);assert.equal(model.positionRows(cash(),false,now).length,0)});
check('Wrong bank, mismatching amount, duplicate/missing source or account fail closed',()=>{for(const mutate of [c=>c.data.bank_positions[0].institution='Bradesco',c=>c.data.bank_positions[0].balance=81,c=>c.data.bank_positions[1].institution_code='341',c=>c.data.bank_positions[1].source_id='synthetic-position-0',c=>c.data.bank_positions[0].source_id=null,c=>c.data.bank_positions.pop(),c=>c.data.cash=101]){const c=cash();mutate(c);assert.equal(model.positionRows(c,true,now).length,0)}});
check('Account metadata does not fall back to Item or collection time',()=>{for(const input of [null,'invalid','2026-09-21T00:00:00Z']){const c=cash();c.data.bank_positions[0].as_of=input;const r=model.positionRows(c,true,now)[0];assert.equal(r.level,'unknown');assert.equal(r.time,null)}});
check('Newer account timestamp with same amount is legitimate metadata',()=>{const c=cash();c.data.bank_positions[0].as_of='2026-09-20T08:00:00Z';const r=model.positionRows(c,true,now)[0];assert.equal(r.level,'same-day');assert.equal(c.data.day['Itaú'].balance,80)});
const trio=()=>status(...banks.map(([institution_code],i)=>row({id:'synthetic-connection-'+i,institution_code})));
check('Completion requires all expected unique connection identities and valid receipts',()=>{assert.equal(model.collectionComplete(trio(),trio(),Date.parse('2026-09-20T08:00:00Z'),now),true);for(const mutate of [s=>s.connections.push({...s.connections[0]}),s=>s.connections[0].id='synthetic-new-connection',s=>s.connections[1].institution_code='341',s=>s.connections[0].last_success_at='2026-09-21T08:00:00Z',s=>s.connections[0].id=null,s=>s.connections.pop()]){const s=trio();mutate(s);assert.equal(model.collectionComplete(s,trio(),Date.parse('2026-09-20T08:00:00Z'),now),false)}});
check('Unknown baseline cannot assert collection completion for a newly connected bank',()=>assert.equal(model.collectionComplete(trio(),null,Date.parse('2026-09-20T08:00:00Z'),now),false));
check('Dashboard layout uses a separate grid row and CSS-only responsive order',()=>{const css=fs.readFileSync(path.join(root,'releases/v280/lts-v225-consolidated.css'),'utf8'),paint=source.slice(source.indexOf('function paintFreshness()'),source.indexOf('function paint()'));assert(paint.includes("anchor.insertAdjacentElement('afterend',box)"));assert(!paint.includes('appendChild'));assert(!/matchMedia|resize/.test(paint));assert(css.includes('grid-template-columns:repeat(3,minmax(0,1fr))'));assert(css.includes('order:1;grid-column:1/-1'));assert(css.includes('@media(max-width:520px){.v168-kpis>.v225-balance-freshness[data-view="Dashboard"]{order:0;grid-template-columns:minmax(0,1fr)}}'))});
const report={passed:checks.length,checks,scope:'Local synthetic pure-model and source-contract checks; no browser, network calls by tested code or SQL execution.'};fs.writeFileSync(path.join(root,'model-results.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report,null,2));
